import {
  ISharePointServiceContext,
  SharePointService
} from "./ISharePointService";
export interface ILicenseAllocation {

  Id:number;

  // New SharePoint columns
  EmployeeName?:{
    Id:number;
    Title:string;
    EMail?:string;
  };

  License?:{
    Id:number;
    Title:string;
  };

  ITRequest?:{
    Id:number;
    Title:string;
  };

  Status?:{
    Value:string;
  } | string;

  AllocatedDate?:string;

  ReleasedDate?:string;


  // Compatibility fields for existing UI
  Employee?:{
    Id:number;
    Title:string;
    EMail?:string;
  };

  Client?:string;

  AllocationDate?:string;

}



export class LicenseAllocationService extends SharePointService {


constructor(
 context:ISharePointServiceContext
){

super(context);

}



public async getAllocations()
:Promise<ILicenseAllocation[]> {


return this.getItems<ILicenseAllocation>(

"License Allocations",

`?$select=
Id,
Status,
AllocatedDate,
ReleasedDate,
EmployeeName/Id,
EmployeeName/Title,
EmployeeName/EMail,
License/Id,
License/Title,
ITRequest/Id,
ITRequest/Title

&$expand=
EmployeeName,
License,
ITRequest

&$orderby=Id desc

&$top=5000`

);


}



public async getClientAllocations(
clientName:string
):Promise<ILicenseAllocation[]> {


return this.getItems<ILicenseAllocation>(

"License Allocations",

`?$select=
Id,
Status,
AllocatedDate,
ReleasedDate,
EmployeeName/Id,
EmployeeName/Title,
EmployeeName/EMail,
License/Id,
License/Title,
ITRequest/Id,
ITRequest/Title

&$expand=
EmployeeName,
License,
ITRequest

&$filter=
ITRequest/Client/Title eq '${clientName}'

&$orderby=Id desc`

);


}



public async createAllocation(
payload:any
):Promise<any>{


return this.postItem(

"License Allocations",

payload

);


}



public async updateAllocation(
id:number,
payload:any
):Promise<void>{


await this.updateItem(

"License Allocations",

id,

payload

);


}


}